exec(open('research.py').read().split('models={')[0])
from sklearn.pipeline import make_pipeline
from sklearn.preprocessing import StandardScaler
from sklearn.linear_model import Ridge
initial=np.array([tr[p][0]['core_temp'] for p in people]);yd=y-initial[groups];pd=np.zeros(len(y));pg=np.zeros(len(y))
for pi in range(14):
 a=groups!=pi;b=~a;m=make_pipeline(StandardScaler(),Ridge(alpha=10000));m.fit(X[a],yd[a]);pd[b]=m.predict(X[b])+np.delete(initial,pi).mean()
 for ii in np.where(b)[0]:
  n=int(X[ii,1])-1; pp=[people[j] for j in range(14) if j!=pi]; vals=[tr[p][n]['core_temp']-tr[p][0]['core_temp'] for p in pp if tr[p][n]['core_temp'] is not None];pg[ii]=np.delete(initial,pi).mean()+np.mean(vals)
for w in np.arange(0,1.01,.1):
 pp=w*pd+(1-w)*pg;ae=abs(pp-y);print('delta',w,ae.mean(),'early',ae[X[:,1]<=5].mean(),'late',ae[X[:,1]>40].mean())
# shrink generic increments and intercept tweaks
for iw in [-.1,0,.1]:
 for dw in [.8,.9,1,1.1]:
  pp=initial.mean()+iw+(pg-initial.mean())*dw;print('cal',iw,dw,np.mean(abs(pp-y)))
